import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int total = 0;
        int best = 0;
        for (int i = 0; i < n; i++) {
            int v = sc.nextInt();
            total += v;
            best = Math.max(best, v);
        }
        System.out.println("一共 " + total + " 条小鱼干");
        System.out.println("最多的那只拿了 " + best + " 条");
    }
}

